# Create API integration modules for Hugging Face ecosystem

# 1. Core Hugging Face API client
hf_api_client = '''#!/usr/bin/env python3
"""
OASIS Hugging Face API Integration
Ultra-lightweight client for 100,000+ models without local dependencies

This module provides pure API access to Hugging Face's model ecosystem
without downloading any models locally, maintaining <5MB footprint.
"""

import requests
import json
import time
import logging
from datetime import datetime
from typing import Dict, List, Optional, Any, Union

class HuggingFaceClient:
    """Ultra-lightweight Hugging Face API client"""

    def __init__(self, token: str, timeout: int = 30):
        """Initialize HF API client"""
        self.token = token
        self.timeout = timeout
        self.base_url = "https://api-inference.huggingface.co"
        self.model_url = f"{self.base_url}/models"

        # Request tracking for business analytics
        self.request_count = 0
        self.total_cost = 0.0
        self.session_start = datetime.now()

        # Common model categories
        self.model_categories = {
            "sentiment": [
                "cardiffnlp/twitter-roberta-base-sentiment-latest",
                "nlptown/bert-base-multilingual-uncased-sentiment",
                "distilbert-base-uncased-finetuned-sst-2-english"
            ],
            "generation": [
                "microsoft/DialoGPT-medium", 
                "gpt2",
                "microsoft/DialoGPT-small"
            ],
            "classification": [
                "facebook/bart-large-mnli",
                "microsoft/deberta-v3-base-mnli-fever-anli"
            ],
            "translation": [
                "Helsinki-NLP/opus-mt-en-de",
                "Helsinki-NLP/opus-mt-en-fr", 
                "Helsinki-NLP/opus-mt-en-es"
            ],
            "summarization": [
                "facebook/bart-large-cnn",
                "google/pegasus-xsum"
            ]
        }

        # Pricing model (per request)
        self.pricing = {
            "sentiment": 0.05,
            "generation": 0.10,
            "classification": 0.07,
            "translation": 0.08,
            "summarization": 0.09,
            "custom": 0.15
        }

        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def _make_request(self, model: str, inputs: Dict, task_type: str = "custom") -> Dict:
        """Make API request with error handling and retry logic"""

        headers = {"Authorization": f"Bearer {self.token}"}
        url = f"{self.model_url}/{model}"

        # Track request for business analytics
        self.request_count += 1
        request_cost = self.pricing.get(task_type, 0.15)
        self.total_cost += request_cost

        for attempt in range(3):  # Retry up to 3 times
            try:
                self.logger.info(f"Making API request to {model} (attempt {attempt + 1})")

                response = requests.post(
                    url, 
                    headers=headers, 
                    json=inputs, 
                    timeout=self.timeout
                )

                if response.status_code == 200:
                    result = response.json()
                    return {
                        "success": True,
                        "result": result,
                        "model": model,
                        "cost": request_cost,
                        "timestamp": datetime.now().isoformat(),
                        "request_id": self.request_count
                    }
                elif response.status_code == 503:
                    # Model loading - wait and retry
                    self.logger.warning(f"Model {model} is loading, waiting 10 seconds...")
                    time.sleep(10)
                    continue
                else:
                    return {
                        "success": False,
                        "error": f"HTTP {response.status_code}: {response.text}",
                        "model": model,
                        "request_id": self.request_count
                    }

            except requests.exceptions.Timeout:
                self.logger.error(f"Timeout for model {model} (attempt {attempt + 1})")
                if attempt == 2:  # Last attempt
                    return {
                        "success": False,
                        "error": "Request timeout after 3 attempts",
                        "model": model,
                        "request_id": self.request_count
                    }
                time.sleep(5)  # Wait before retry

            except Exception as e:
                return {
                    "success": False,
                    "error": f"Request failed: {str(e)}",
                    "model": model,
                    "request_id": self.request_count
                }

        return {
            "success": False,
            "error": "Max retries exceeded",
            "model": model,
            "request_id": self.request_count
        }

    def analyze_sentiment(self, text: str, model: Optional[str] = None) -> Dict:
        """Analyze sentiment with automatic model selection"""

        if not text.strip():
            return {"success": False, "error": "Empty text provided"}

        model = model or self.model_categories["sentiment"][0]
        inputs = {"inputs": text}

        return self._make_request(model, inputs, "sentiment")

    def generate_text(self, prompt: str, model: Optional[str] = None, 
                     max_length: int = 100, temperature: float = 0.7) -> Dict:
        """Generate text with configurable parameters"""

        if not prompt.strip():
            return {"success": False, "error": "Empty prompt provided"}

        model = model or self.model_categories["generation"][0]
        inputs = {
            "inputs": prompt,
            "parameters": {
                "max_length": max_length,
                "temperature": temperature,
                "do_sample": True,
                "top_p": 0.9
            }
        }

        return self._make_request(model, inputs, "generation")

    def classify_text(self, text: str, candidate_labels: List[str], 
                     model: Optional[str] = None) -> Dict:
        """Zero-shot text classification"""

        if not text.strip():
            return {"success": False, "error": "Empty text provided"}

        if not candidate_labels:
            return {"success": False, "error": "No candidate labels provided"}

        model = model or self.model_categories["classification"][0]
        inputs = {
            "inputs": text,
            "parameters": {"candidate_labels": candidate_labels}
        }

        return self._make_request(model, inputs, "classification")

    def translate_text(self, text: str, source_lang: str = "en", 
                      target_lang: str = "de") -> Dict:
        """Translate text between languages"""

        if not text.strip():
            return {"success": False, "error": "Empty text provided"}

        # Find appropriate translation model
        model_name = f"Helsinki-NLP/opus-mt-{source_lang}-{target_lang}"
        inputs = {"inputs": text}

        return self._make_request(model_name, inputs, "translation")

    def summarize_text(self, text: str, model: Optional[str] = None,
                      max_length: int = 150, min_length: int = 30) -> Dict:
        """Summarize long text"""

        if not text.strip():
            return {"success": False, "error": "Empty text provided"}

        model = model or self.model_categories["summarization"][0]
        inputs = {
            "inputs": text,
            "parameters": {
                "max_length": max_length,
                "min_length": min_length,
                "do_sample": False
            }
        }

        return self._make_request(model, inputs, "summarization")

    def get_model_info(self, model: str) -> Dict:
        """Get information about a specific model"""

        try:
            url = f"https://huggingface.co/api/models/{model}"
            response = requests.get(url, timeout=self.timeout)

            if response.status_code == 200:
                return {
                    "success": True,
                    "info": response.json(),
                    "model": model
                }
            else:
                return {
                    "success": False,
                    "error": f"Model info not available: {response.status_code}",
                    "model": model
                }

        except Exception as e:
            return {
                "success": False,
                "error": f"Failed to get model info: {str(e)}",
                "model": model
            }

    def list_available_models(self, task: Optional[str] = None) -> List[str]:
        """List available models by task category"""

        if task and task in self.model_categories:
            return self.model_categories[task]
        elif task:
            return []  # Task not found
        else:
            # Return all models
            all_models = []
            for category_models in self.model_categories.values():
                all_models.extend(category_models)
            return all_models

    def get_session_stats(self) -> Dict:
        """Get session statistics for business intelligence"""

        runtime = datetime.now() - self.session_start

        return {
            "session_duration": str(runtime).split('.')[0],  # Remove microseconds
            "total_requests": self.request_count,
            "total_cost": round(self.total_cost, 3),
            "average_cost_per_request": round(self.total_cost / max(self.request_count, 1), 3),
            "session_start": self.session_start.isoformat(),
            "models_available": sum(len(models) for models in self.model_categories.values())
        }

    def batch_process(self, tasks: List[Dict]) -> List[Dict]:
        """Process multiple tasks in batch"""

        results = []

        for i, task in enumerate(tasks):
            self.logger.info(f"Processing batch task {i + 1}/{len(tasks)}")

            task_type = task.get("type")
            task_data = task.get("data", {})

            if task_type == "sentiment":
                result = self.analyze_sentiment(**task_data)
            elif task_type == "generation":
                result = self.generate_text(**task_data)
            elif task_type == "classification":
                result = self.classify_text(**task_data)
            elif task_type == "translation":
                result = self.translate_text(**task_data)
            elif task_type == "summarization":
                result = self.summarize_text(**task_data)
            else:
                result = {"success": False, "error": f"Unknown task type: {task_type}"}

            result["batch_index"] = i
            results.append(result)

            # Small delay to avoid rate limiting
            time.sleep(0.1)

        return results

    def health_check(self) -> Dict:
        """Check API connectivity and model availability"""

        # Test with a simple sentiment analysis
        test_result = self.analyze_sentiment("OASIS is working great!")

        health_status = {
            "api_accessible": test_result["success"],
            "test_model": self.model_categories["sentiment"][0],
            "response_time": "< 30s" if test_result["success"] else "timeout",
            "session_stats": self.get_session_stats(),
            "timestamp": datetime.now().isoformat()
        }

        if not test_result["success"]:
            health_status["error"] = test_result.get("error", "Unknown error")

        return health_status
'''

with open(f"{base_dir}/src/api/hf_client.py", "w", encoding="utf-8") as f:
