model_manager = '''#!/usr/bin/env python3
"""
OASIS Model Manager
Advanced model selection, performance tracking, and optimization
"""

import json
import time
from datetime import datetime, timedelta
from typing import Dict, List, Optional, Any
from collections import defaultdict, deque

class ModelManager:
    """Advanced model management and performance optimization"""

    def __init__(self, hf_client):
        """Initialize with HuggingFace client"""
        self.hf_client = hf_client
        self.performance_history = defaultdict(lambda: deque(maxlen=100))
        self.model_preferences = {}
        self.fallback_models = {}
        self.load_configuration()

    def load_configuration(self):
        """Load model configuration and preferences"""
        # Default fallback models for each category
        self.fallback_models = {
            "sentiment": [
                "cardiffnlp/twitter-roberta-base-sentiment-latest",
                "distilbert-base-uncased-finetuned-sst-2-english",
                "nlptown/bert-base-multilingual-uncased-sentiment"
            ],
            "generation": [
                "microsoft/DialoGPT-medium",
                "gpt2", 
                "microsoft/DialoGPT-small"
            ],
            "classification": [
                "facebook/bart-large-mnli",
                "microsoft/deberta-v3-base-mnli-fever-anli"
            ]
        }

    def select_best_model(self, task: str, requirements: Dict = None) -> str:
        """Select best model based on performance history and requirements"""

        available_models = self.fallback_models.get(task, [])
        if not available_models:
            return None

        requirements = requirements or {}
        priority = requirements.get("priority", "balanced")  # speed, accuracy, balanced

        # If no performance history, return default (first model)
        if not any(self.performance_history[model] for model in available_models):
            return available_models[0]

        # Calculate scores for each model
        model_scores = {}

        for model in available_models:
            history = list(self.performance_history[model])
            if not history:
                model_scores[model] = 0.5  # Default score for untested models
                continue

            # Calculate average success rate
            success_rate = sum(1 for record in history if record["success"]) / len(history)

            # Calculate average response time (lower is better)
            response_times = [record["response_time"] for record in history if "response_time" in record]
            avg_response_time = sum(response_times) / len(response_times) if response_times else 30

            # Normalize response time (assume 30s is max acceptable)
            speed_score = max(0, 1 - (avg_response_time / 30))

            # Combined score based on priority
            if priority == "speed":
                model_scores[model] = speed_score * 0.7 + success_rate * 0.3
            elif priority == "accuracy":
                model_scores[model] = success_rate * 0.8 + speed_score * 0.2
            else:  # balanced
                model_scores[model] = success_rate * 0.6 + speed_score * 0.4

        # Return model with highest score
        best_model = max(model_scores.items(), key=lambda x: x[1])[0]
        return best_model

    def track_performance(self, model: str, result: Dict):
        """Track model performance for future optimization"""

        performance_record = {
            "timestamp": datetime.now().isoformat(),
            "success": result.get("success", False),
            "error": result.get("error"),
            "cost": result.get("cost", 0),
            "response_time": result.get("response_time", 30)  # Estimate if not provided
        }

        # Add response time if we can calculate it
        if "timestamp" in result:
            try:
                result_time = datetime.fromisoformat(result["timestamp"])
                # This would need to be calculated from request start time
                # For now, we'll use a default estimation
                performance_record["response_time"] = 5  # Default 5 second estimation
            except:
                pass

        self.performance_history[model].append(performance_record)

    def get_model_stats(self, model: str) -> Dict:
        """Get performance statistics for a specific model"""

        history = list(self.performance_history[model])
        if not history:
            return {
                "model": model,
                "total_requests": 0,
                "success_rate": 0,
                "average_cost": 0,
                "average_response_time": 0,
                "status": "untested"
            }

        total_requests = len(history)
        successful_requests = sum(1 for record in history if record["success"])
        success_rate = successful_requests / total_requests

        costs = [record["cost"] for record in history if "cost" in record]
        average_cost = sum(costs) / len(costs) if costs else 0

        response_times = [record["response_time"] for record in history if "response_time" in record]
        average_response_time = sum(response_times) / len(response_times) if response_times else 0

        # Determine status
        if success_rate > 0.9:
            status = "excellent"
        elif success_rate > 0.7:
            status = "good"
        elif success_rate > 0.5:
            status = "fair"
        else:
            status = "poor"

        return {
            "model": model,
            "total_requests": total_requests,
            "success_rate": round(success_rate, 3),
            "average_cost": round(average_cost, 3),
            "average_response_time": round(average_response_time, 2),
            "status": status,
            "last_used": history[-1]["timestamp"] if history else None
        }

    def get_performance_summary(self) -> Dict:
        """Get overall performance summary across all models"""

        all_models = set()
        for category_models in self.fallback_models.values():
            all_models.update(category_models)

        model_stats = {}
        total_requests = 0
        total_cost = 0

        for model in all_models:
            stats = self.get_model_stats(model)
            model_stats[model] = stats
            total_requests += stats["total_requests"]
            total_cost += stats["average_cost"] * stats["total_requests"]

        return {
            "total_models_tracked": len(all_models),
            "total_requests_processed": total_requests,
            "total_estimated_cost": round(total_cost, 3),
            "model_statistics": model_stats,
            "generated_at": datetime.now().isoformat()
        }

    def recommend_optimizations(self) -> List[Dict]:
        """Recommend model optimizations based on performance data"""

        recommendations = []

        for task, models in self.fallback_models.items():
            task_stats = {model: self.get_model_stats(model) for model in models}

            # Find best and worst performing models
            tested_models = {k: v for k, v in task_stats.items() if v["total_requests"] > 0}

            if len(tested_models) < 2:
                continue

            best_model = max(tested_models.items(), key=lambda x: x[1]["success_rate"])
            worst_model = min(tested_models.items(), key=lambda x: x[1]["success_rate"])

            if best_model[1]["success_rate"] - worst_model[1]["success_rate"] > 0.2:
                recommendations.append({
                    "type": "model_replacement",
                    "task": task,
                    "current_model": worst_model[0],
                    "recommended_model": best_model[0],
                    "improvement": f"{((best_model[1]['success_rate'] - worst_model[1]['success_rate']) * 100):.1f}% better success rate",
                    "priority": "high" if worst_model[1]["success_rate"] < 0.5 else "medium"
                })

            # Check for cost optimization opportunities
            if len(tested_models) >= 2:
                cost_efficient = min(tested_models.items(), key=lambda x: x[1]["average_cost"])
                if cost_efficient[1]["success_rate"] > 0.7:
                    recommendations.append({
                        "type": "cost_optimization",
                        "task": task,
                        "recommended_model": cost_efficient[0],
                        "benefit": f"${cost_efficient[1]['average_cost']:.3f} per request vs average",
                        "priority": "low"
                    })

        return recommendations

    def auto_failover(self, task: str, failed_model: str) -> Optional[str]:
        """Automatically select failover model when primary fails"""

        available_models = self.fallback_models.get(task, [])
        if failed_model in available_models:
            # Remove failed model from list and select next best
            remaining_models = [m for m in available_models if m != failed_model]
            if remaining_models:
                return self.select_best_model(task)

        return None

    def cleanup_old_data(self, days_to_keep: int = 7):
        """Clean up old performance data to manage memory"""

        cutoff_date = datetime.now() - timedelta(days=days_to_keep)

        for model in self.performance_history:
            history = self.performance_history[model]
            # Keep only recent records
            filtered_history = deque(
                [record for record in history 
                 if datetime.fromisoformat(record["timestamp"]) > cutoff_date],
                maxlen=100
            )
            self.performance_history[model] = filtered_history
