        services_used = set(t["service_type"] for t in transactions)
        all_services = set(self.pricing_config["services"].keys())
        unused_services = all_services - services_used

        if unused_services:
            recommendations.append(f"Try our additional services: {', '.join(unused_services)}")

        # Recent activity
        recent_transactions = [
            t for t in transactions
            if datetime.fromisoformat(t["timestamp"]) > datetime.now() - timedelta(days=30)
        ]

        if not recent_transactions:
            recommendations.append("We haven't seen you recently - check out our new features!")

        return recommendations

    def export_financial_report(self, format_type: str = "json") -> Dict:
        """Export comprehensive financial report"""

        analytics = self.get_revenue_analytics(days=365)  # Full year

        report = {
            "report_generated": datetime.now().isoformat(),
